nextflow_process {

    name "Test Process SENTIEON_DEDUP"
    tag "modules_nfcore"
    tag "modules"
    tag "sentieon"
    tag "dedup"
    tag "sentieon/dedup"

    script "../main.nf"
    process "SENTIEON_DEDUP"

    config "./nextflow.config"

    test("Test marking duplicates, bam") {

        when {
            params {
                module_args = ''
                module_args2 = ''
                module_args3 = ''
                module_args4 = ''
                module_prefix = "test.dedup.bam"
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true) ],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true) ]
                ]
                input[1] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                input[2] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    file(process.out.bai[0][1]).name,
                    path(process.out.score[0][1]).contains("SentieonCommandLine"),
                    path(process.out.metrics[0][1]).contains("SentieonCommandLine"),
                    path(process.out.metrics_multiqc_tsv[0][1]).contains("SentieonCommandLine"),
                    process.out.findAll { key, val -> key.startsWith("versions") }
                    ).match() }
            )
        }
    }

    test("Test removing duplicates, cram") {

        when {
            params {
                module_args = ''
                module_args2 = ''
                module_args3 = ''
                module_args4 = '--rmdup'
                module_prefix = "test.dedup.cram"
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true) ],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true) ]
                ]
                input[1] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                input[2] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)]
                """
            }
        }

        then {
            def fasta = 'https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/genomics/sarscov2/genome/genome.fasta'
            assert process.success
            assertAll(
                { assert snapshot(
                    cram(process.out.cram[0][1], fasta).getReadsMD5(),
                    file(process.out.crai[0][1]).name,
                    path(process.out.score[0][1]).contains("SentieonCommandLine"),
                    path(process.out.metrics[0][1]).contains("SentieonCommandLine"),
                    path(process.out.metrics_multiqc_tsv[0][1]).contains("SentieonCommandLine"),
                    process.out.findAll { key, val -> key.startsWith("versions") }
                    ).match() }
            )
        }
    }

    test("Test stub") {
        options "-stub"
        when {
            params {
                module_args = ''
                module_args2 = ''
                module_args3 = ''
                module_args4 = ''
                module_prefix = ''
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.single_end.sorted.bam', checkIfExists: true) ],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.single_end.sorted.bam.bai', checkIfExists: true) ]
                ]
                input[1] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                input[2] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(process.out).match() }
            )
        }
    }
}

